    private readonly EntityManagerInterface $entityManager;
    private readonly PropertyAccessorInterface $propertyAccessor;

    public function __construct(EntityManagerInterface $entityManager, PropertyAccessorInterface $propertyAccessor)
    {
        parent::__construct();
        $this
            ->setDescription('Update supplier number of <Entity> parameter for an array of corresponding values.')
            ->addArgument('entity', InputArgument::REQUIRED, 'Entity class for replacing supplier number values.')
            ->addArgument('locationDefaultPropertyAccess', InputArgument::OPTIONAL, '"supplierErp" : supplierErp is the default property access to Location from VendorWarrantyClaim entity.', 'supplierErp')
            ->addArgument('locationSecondaryPropertyAccess', InputArgument::OPTIONAL, '"factory" : factory is the secondary property access to Location from VendorWarrantyClaim entity.', 'factory');

        $this->entityManager = $entityManager;
        $this->propertyAccessor = $propertyAccessor;
    }

    protected function execute(InputInterface $input, OutputInterface $output): int
    {
        $argEntityClass = $input->getArgument('entity');
        $locationDefaultPropertyAccess = $input->getArgument('locationDefaultPropertyAccess');
        $locationSecondaryPropertyAccess = $input->getArgument('locationSecondaryPropertyAccess');

        if (!class_exists($argEntityClass)) {
            throw new \LogicException(\sprintf('Class %s does not exist', $argEntityClass));
        }

        $repository = $this->entityManager->getRepository($argEntityClass);
        $i = 0;
        foreach ($repository->findAll() as $row) {
            $erp = null;
            if (property_exists($argEntityClass, $locationDefaultPropertyAccess)) {
                $erp = ($defaultProperty = $this->propertyAccessor->getValue($row, $locationDefaultPropertyAccess)) instanceof Location ? $defaultProperty->getErp() : $defaultProperty;
                if (null === $erp && property_exists($argEntityClass, $locationSecondaryPropertyAccess)) {
                    $erp = ($defaultProperty = $this->propertyAccessor->getValue($row, $locationSecondaryPropertyAccess)) instanceof Location ? $defaultProperty->getErp() : $defaultProperty;
                }
            }

            if (null === $erp || \in_array((int) $erp, $this->erps, true)) {
                $output->writeln(\sprintf('No ERP found for %s #%s', $argEntityClass, $row->getId()));
                continue;
            }

            if (null === $row->getSupplierNumber() || '' === $row->getSupplierNumber()) {
                continue;
            }

            // Looking for existing supplier number in the array of values given
            $erp = $this->commonFactories[$erp];
            $key = \sprintf('%d-%s', $erp, $row->getSupplierNumber());
            if (isset($this->newSupplierValues[$key])) {
                $row->setSupplierNumber($this->newSupplierValues[$key]);
            // Set new supplier number with prefix only for ERP values set in the erps attribute.
            } else {
                $row->setSupplierNumber(\sprintf('S%d%s', mb_substr((string) $erp, 0, 2), $row->getSupplierNumber()));
            }

            $this->entityManager->persist($row);
            // Proceeding flush every 10000 rows
            if (($i % 10000) === 0) {
                $this->entityManager->flush();
            }
            ++$i;
        }

        $this->entityManager->flush();
        $output->writeln('');

        return Command::SUCCESS;
    }
}
